var JSON_TYPES = ['string','number','integer','boolean','array','object'];
function parseParamLines(text){
  var out=[], lines=String(text||'').split(/\r?\n/);
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln || ln.charAt(0)==='#') continue;
    var parts=ln.split('|');
    var name=(parts[0]||'').trim();
    if(!name) continue;
    var type=(parts[1]||'string').trim().toLowerCase();
    var desc=(parts[2]||'').trim();
    var req=/^(y|yes|true|1|required)$/i.test((parts[3]||'').trim());
    var en=(parts[4]||'').trim();
    var p={name:name, type:type, description:desc, required:req};
    if(en) p['enum']=en.split(',').map(function(s){ return s.trim(); }).filter(Boolean);
    out.push(p);
  }
  return out;
}
function buildSchema(name, description, params, style){
  var props={}, required=[];
  for(var i=0;i<params.length;i++){
    var p=params[i];
    var s={type: JSON_TYPES.indexOf(p.type)>=0 ? p.type : 'string'};
    if(p.description) s.description=p.description;
    if(p['enum'] && p['enum'].length) s['enum']=p['enum'];
    if(s.type==='array') s.items={type:'string'};
    props[p.name]=s;
    if(p.required) required.push(p.name);
  }
  var parameters={type:'object', properties:props};
  if(required.length) parameters.required=required;
  parameters.additionalProperties=false;
  if(style==='anthropic'){
    return {name:name, description:description, input_schema:parameters};
  }
  if(style==='mcp'){
    return {name:name, description:description, inputSchema:parameters};
  }
  return {type:'function', 'function':{name:name, description:description, parameters:parameters}};
}
function lintSchema(name, description, params){
  var errs=[], warns=[];
  if(!name) errs.push('工具名不能为空');
  else if(!/^[a-zA-Z0-9_-]{1,64}$/.test(name)) errs.push('工具名须为 1-64 位字母/数字/下划线/连字符');
  if(!description) warns.push('缺少描述，模型难以判断何时调用该工具');
  else if(description.length<15) warns.push('描述过短（建议 >=15 字），模型选择准确率会下降');
  if(!params.length) warns.push('未定义参数，若工具确实无入参可忽略');
  var seen={};
  for(var i=0;i<params.length;i++){
    var p=params[i];
    if(seen[p.name]) errs.push('参数名重复：'+p.name);
    seen[p.name]=1;
    if(!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(p.name)) errs.push('参数名非法：'+p.name);
    if(JSON_TYPES.indexOf(p.type)<0) errs.push('未知类型：'+p.type+'（'+p.name+'）');
    if(!p.description) warns.push('参数 '+p.name+' 缺少描述');
  }
  if(params.length>10) warns.push('参数过多（'+params.length+'），建议拆分为多个工具');
  return {valid: errs.length===0, errors:errs, warnings:warns};
}
function schemaTokenCost(schema){
  var s=JSON.stringify(schema);
  return {chars:s.length, approxTokens:Math.ceil(s.length/4)};
}
function validateCall(schema, argsObj){
  var params = schema && (schema.parameters || schema.input_schema || schema.inputSchema
              || (schema['function'] && schema['function'].parameters));
  if(!params) return {valid:false, errors:['无法从 schema 中定位参数定义']};
  var errs=[], props=params.properties||{}, req=params.required||[];
  for(var i=0;i<req.length;i++){
    if(!(req[i] in argsObj)) errs.push('缺少必填参数：'+req[i]);
  }
  for(var k in argsObj){
    if(!argsObj.hasOwnProperty(k)) continue;
    if(!props[k]){ errs.push('未声明的参数：'+k); continue; }
    var want=props[k].type, got=Array.isArray(argsObj[k])?'array':typeof argsObj[k];
    if(want==='integer'){ if(got!=='number' || argsObj[k]%1!==0) errs.push(k+' 应为 integer'); }
    else if(want==='number'){ if(got!=='number') errs.push(k+' 应为 number'); }
    else if(want && want!==got) errs.push(k+' 应为 '+want+'，实际 '+got);
    if(props[k]['enum'] && props[k]['enum'].indexOf(argsObj[k])<0) errs.push(k+' 不在枚举范围内');
  }
  return {valid: errs.length===0, errors:errs};
}
if (typeof module !== 'undefined' && module.exports) { module.exports = { parseParamLines:parseParamLines, buildSchema:buildSchema, lintSchema:lintSchema, schemaTokenCost:schemaTokenCost, validateCall:validateCall, JSON_TYPES:JSON_TYPES }; }
if (typeof window !== 'undefined') { window.AgentSchemaForgePure = { parseParamLines:parseParamLines, buildSchema:buildSchema, lintSchema:lintSchema, schemaTokenCost:schemaTokenCost, validateCall:validateCall, JSON_TYPES:JSON_TYPES }; }
